    assertEquals("Purpose for signing", sic.getSignatureDescription());
    assertEquals("2018-06-10T09:00:54Z", sic.formatExecutionTime());
    assertEquals(CanonicalizationMethod.INCLUSIVE, sic.getCanonicalizationMethod());
}

