    assertEquals(60000, ref3.getLumModArray(0).getVal());
    assertEquals(40000, ref3.getLumOffArray(0).getVal());
    assertEquals("accent1", ref3.getVal().toString());
    assertEquals(new Color(149, 179, 215), s3.getFillColor());
    // darker 25%
