    assertTrue(tc.getTcPr().getLnB().isSetNoFill());
    assertTrue(tc.getTcPr().getLnT().isSetNoFill());
    assertTrue(tc.getTcPr().getLnL().isSetNoFill());
    assertTrue(tc.getTcPr().getLnR().isSetNoFill());
