@Test
public void testExportToXML() throws Exception {
    try (XSSFWorkbook wb = XSSFTestDataSamples.openSampleWorkbook("CustomXMLMappings.xlsx")) {
        boolean found = false;
        for (POIXMLDocumentPart p : wb.getRelations()) {
            if (!(p instanceof MapInfo)) {
