            String argomento = xml.split("<ARGOMENTO>")[1].split("</ARGOMENTO>")[0].trim();
            String progetto = xml.split("<PROGETTO>")[1].split("</PROGETTO>")[0].trim();
            String crediti = xml.split("<CREDITI>")[1].split("</CREDITI>")[0].trim();
