@Ignore("Crashes the JVM because of documented JVM behavior with concurrent writing/reading of zip-files, " + "see http://www.oracle.com/technetwork/java/javase/documentation/overview-156328.html")
@Test
public void bug53515a() throws Exception {
    File out = new File("Test.xlsx");
    assertTrue(!out.exists() || out.delete());
    for (int i = 0; i < 2; i++) {
        final SXSSFWorkbook wb;
        if (out.exists()) {
            wb = new SXSSFWorkbook((XSSFWorkbook) WorkbookFactory.create(out));
        } else {
            wb = new SXSSFWorkbook(10);
        }
        try {
            FileOutputStream outSteam = new FileOutputStream(out);
            if (i == 0) {
                populateWorkbook(wb);
            } else {
                System.gc();
                System.gc();
                System.gc();
            }
            wb.write(outSteam);
            // assertTrue(wb.dispose());
            outSteam.close();
        } finally {
            assertTrue(wb.dispose());
        }
        wb.close();
    }
    assertTrue(out.exists());
    assertTrue(out.delete());
}

