    assertTrue(shapes.get(1) instanceof XSSFShapeGroup);
    shapes = draw.getShapes((XSSFShapeGroup) shapes.get(1));
    assertEquals(1, shapes.size());
    assertTrue(shapes.get(0) instanceof XSSFSimpleShape);
