/**
 * Test that fonts get added properly
 */
@Test
public void testFindFont() throws IOException {
    XSSFWorkbook wb = new XSSFWorkbook();
    assertEquals(1, wb.getNumberOfFonts());
    XSSFSheet s = wb.createSheet();
    s.createRow(0);
    s.createRow(1);
    s.getRow(0).createCell(0);
    s.getRow(1).createCell(0);
    assertEquals(1, wb.getNumberOfFonts());
    XSSFFont f1 = wb.getFontAt(0);
    assertFalse(f1.getBold());
    // Check that asking for the same font
    //  multiple times gives you the same thing.
    // Otherwise, our tests wouldn't work!
    assertSame(wb.getFontAt(0), wb.getFontAt(0));
    assertEquals(wb.getFontAt(0), wb.getFontAt(0));
    // Look for a new font we have
    //  yet to add
    assertNull(wb.findFont(false, IndexedColors.INDIGO.getIndex(), (short) 22, "Thingy", false, true, (short) 2, (byte) 2));
    assertNull(wb.getStylesSource().findFont(false, new XSSFColor(IndexedColors.INDIGO, new DefaultIndexedColorMap()), (short) 22, "Thingy", false, true, (short) 2, (byte) 2));
    XSSFFont nf = wb.createFont();
    assertEquals(2, wb.getNumberOfFonts());
    assertEquals(1, nf.getIndexAsInt());
    assertEquals(nf, wb.getFontAt(1));
    nf.setBold(false);
    nf.setColor(IndexedColors.INDIGO.getIndex());
    nf.setFontHeight((short) 22);
    nf.setFontName("Thingy");
    nf.setItalic(false);
    nf.setStrikeout(true);
    nf.setTypeOffset((short) 2);
    nf.setUnderline((byte) 2);
    assertEquals(2, wb.getNumberOfFonts());
    assertEquals(nf, wb.getFontAt(1));
    assertTrue(wb.getFontAt(0) != wb.getFontAt(1));
    // Find it now
    assertNotNull(wb.findFont(false, IndexedColors.INDIGO.getIndex(), (short) 22, "Thingy", false, true, (short) 2, (byte) 2));
    assertNotNull(wb.getStylesSource().findFont(false, new XSSFColor(IndexedColors.INDIGO, new DefaultIndexedColorMap()), (short) 22, "Thingy", false, true, (short) 2, (byte) 2));
    XSSFFont font = wb.findFont(false, IndexedColors.INDIGO.getIndex(), (short) 22, "Thingy", false, true, (short) 2, (byte) 2);
    assertNotNull(font);
    assertEquals(1, font.getIndexAsInt());
    assertEquals(nf, wb.findFont(false, IndexedColors.INDIGO.getIndex(), (short) 22, "Thingy", false, true, (short) 2, (byte) 2));
    assertEquals(nf, wb.getStylesSource().findFont(false, new XSSFColor(IndexedColors.INDIGO, new DefaultIndexedColorMap()), (short) 22, "Thingy", false, true, (short) 2, (byte) 2));
    wb.close();
}

