    assertEquals(AnchorType.MOVE_AND_RESIZE, anchor.getAnchorType());
    anchor.setAnchorType(AnchorType.DONT_MOVE_AND_RESIZE);
    assertEquals(AnchorType.DONT_MOVE_AND_RESIZE, anchor.getAnchorType());
