    // true, true
    checkColumnGroupIsCollapsed(cols.getColArray(3), 10, 11);
    // false, true
    checkColumnGroup(cols.getColArray(4), 12, 12);
    checkColumnGroup(cols.getColArray(5), 13, 13, false, false);
