        assertEquals("34.56", t.getCTTable().getTableColumns().getTableColumnArray(1).getName());
        assertEquals("ABCD", t.getCTTable().getTableColumns().getTableColumnArray(2).getName());
        // Done
        IOUtils.closeQuietly(wb2);
    }
}

