        assertEquals(12.32, run.getFontSize(), 0.01);
        run.setFontSize(-1.0);
        assertEquals(11.0, run.getFontSize(), 0.01);
        run.setFontSize(-1.0);
        assertEquals(11.0, run.getFontSize(), 0.01);
        try {
            run.setFontSize(0.9);
