    assertEquals(false, cf_4_1.getSubValue(CharFlagsTextProp.ENABLE_NUMBERING_1_IDX));
    assertEquals(false, cf_4_1.getSubValue(CharFlagsTextProp.ENABLE_NUMBERING_2_IDX));
