@Test
public void testReOrder3swap() throws IOException {
    // Has three slides
    assertEquals(3, ss_three.getSlides().size());
    HSLFSlide s1 = ss_three.getSlides().get(0);
    HSLFSlide s2 = ss_three.getSlides().get(1);
    HSLFSlide s3 = ss_three.getSlides().get(2);
