        // Finally, check we can do a similar 512byte one too
        fs = new POIFSFileSystem(_samples.openResourceAsStream("BlockSize512.zvi"));
        assertTrue(fs.getRoot().getEntryCount() > 3);
        checkAllDirectoryContents(fs.getRoot());
    }
}

