/**
 * Tests what happens to area refs when a range of rows from inside, or overlapping are
 * moved
 */
@Test
public void testShiftAreasSourceRows() {
    // all these operations are on an area ref spanning rows 10 to 20
    AreaPtg aptg = createAreaPtgRow(10, 20);
    confirmAreaRowShift(aptg, 9, 21, 20, 30, 40);
    confirmAreaRowShift(aptg, 10, 21, 20, 30, 40);
    confirmAreaRowShift(aptg, 9, 20, 20, 30, 40);
    // simple expansion of top
    confirmAreaRowShift(aptg, 8, 11, -3, 7, 20);
    // rows containing area top being shifted down:
    confirmAreaRowShift(aptg, 8, 11, 3, 13, 20);
    confirmAreaRowShift(aptg, 8, 11, 7, 17, 20);
    confirmAreaRowShift(aptg, 8, 11, 8, 18, 20);
    // note behaviour changes here
    confirmAreaRowShift(aptg, 8, 11, 9, 12, 20);
    confirmAreaRowShift(aptg, 8, 11, 10, 12, 21);
    confirmAreaRowShift(aptg, 8, 11, 12, 12, 23);
    // ignored
    confirmAreaRowShift(aptg, 8, 11, 13, 10, 20);
    // rows from within being moved:
    // stay within - no change
    confirmAreaRowShift(aptg, 12, 16, 3, 10, 20);
    // move completely out - no change
    confirmAreaRowShift(aptg, 11, 19, 20, 10, 20);
    // moved exactly to top - no change
    confirmAreaRowShift(aptg, 16, 17, -6, 10, 20);
    // truncation at top
    confirmAreaRowShift(aptg, 16, 17, -7, 11, 20);
    // moved exactly to bottom - no change
    confirmAreaRowShift(aptg, 12, 16, 4, 10, 20);
    // truncation at bottom
    confirmAreaRowShift(aptg, 12, 16, 6, 10, 17);
    // rows containing area bottom being shifted up:
    // simple contraction at bottom
    confirmAreaRowShift(aptg, 18, 22, -1, 10, 19);
    // simple contraction at bottom
    confirmAreaRowShift(aptg, 18, 22, -7, 10, 13);
    // top calculated differently here
    confirmAreaRowShift(aptg, 18, 22, -8, 10, 17);
    confirmAreaRowShift(aptg, 18, 22, -9, 9, 17);
    // no change because range would be turned inside out
    confirmAreaRowShift(aptg, 18, 22, -15, 10, 20);
    // dest truncates top (even though src is from inside range)
    confirmAreaRowShift(aptg, 15, 19, -7, 13, 20);
    // complex: src encloses bottom, dest encloses top
    confirmAreaRowShift(aptg, 19, 23, -12, 7, 18);
    // simple expansion at bottom
    confirmAreaRowShift(aptg, 18, 22, 5, 10, 25);
}

