    assertEquals(CellType.FORMULA, cell.getCellType());
    assertEquals("IF(A1<>\"\",IF(C1<>\"\",MID(A1,1,2),\"c1\"),\"c2\")", cell.getCellFormula());
    ev.evaluateFormulaCell(cell);
    assertEquals("ab", cell.getStringCellValue());
    assertEquals(CellType.FORMULA, cell.getCellType());
    assertEquals("IF(A1<>\"\",IF(C1<>\"\",MID(A1,1,2),\"c1\"),\"c2\")", cell.getCellFormula());
