    }
    final double totalTime_s = (populateSheetTime + autoSizeColumnsTime) / 1000;
    if (logger.check(POILogger.DEBUG)) {
        logger.log(POILogger.DEBUG, "Total time: " + totalTime_s + " s");
    }
    wb.close();
