@Test
public final void test45338() throws IOException {
    Workbook wb = _testDataProvider.createWorkbook();
    int num0 = wb.getNumberOfFontsAsInt();
    Sheet s = wb.createSheet();
    s.createRow(0);
    s.createRow(1);
