@Test
public void numericCells() throws Exception {
    Workbook workbook = _testDataProvider.createWorkbook();
    fixFonts(workbook);
    DataFormat df = workbook.getCreationHelper().createDataFormat();
    Sheet sheet = workbook.createSheet();
    trackColumnsForAutoSizingIfSXSSF(sheet);
    Row row = sheet.createRow(0);
    // getCachedFormulaResult() returns 0 for not evaluated formula cells
    row.createCell(0).setCellValue(0);
    row.createCell(1).setCellValue(10);
    row.createCell(2).setCellValue("10");
    // a formula that returns '10'
    row.createCell(3).setCellFormula("(A1+B1)*1.0");
    // numeric cell with a custom style
    Cell cell4 = row.createCell(4);
    CellStyle style4 = workbook.createCellStyle();
    style4.setDataFormat(df.getFormat("0.0000"));
    cell4.setCellStyle(style4);
    // formatted as '10.0000'
    cell4.setCellValue(10);
    row.createCell(5).setCellValue("10.0000");
    // autosize not-evaluated cells, formula cells are sized as if the result is 0
    for (int i = 0; i < 6; i++) sheet.autoSizeColumn(i);
    // width of '0' is less then width of '10'
    assertTrue(sheet.getColumnWidth(0) < sheet.getColumnWidth(1));
    // 10 and '10' should be sized equally
    assertEquals(sheet.getColumnWidth(1), sheet.getColumnWidth(2));
    // formula result is unknown, the width is calculated  for '0'
    assertEquals(sheet.getColumnWidth(3), sheet.getColumnWidth(0));
    // 10.0000 and '10.0000'
    assertEquals(sheet.getColumnWidth(4), sheet.getColumnWidth(5));
    // evaluate formulas and re-autosize
    evaluateWorkbook(workbook);
    for (int i = 0; i < 6; i++) sheet.autoSizeColumn(i);
    // width of '0' is less then width of '10'
    assertTrue(sheet.getColumnWidth(0) < sheet.getColumnWidth(1));
    // columns 1, 2 and 3 should have the same width
    assertEquals(sheet.getColumnWidth(1), sheet.getColumnWidth(2));
    // columns 1, 2 and 3 should have the same width
    assertEquals(sheet.getColumnWidth(2), sheet.getColumnWidth(3));
    // 10.0000 and '10.0000'
    assertEquals(sheet.getColumnWidth(4), sheet.getColumnWidth(5));
    workbook.close();
}

