@Test
public void testModifyArrayCells_mergeCellsMulti() throws IOException {
    Workbook workbook = _testDataProvider.createWorkbook();
    Sheet sheet = workbook.createSheet();
    int expectedNumMergedRegions = 0;
    assertEquals(expectedNumMergedRegions, sheet.getNumMergedRegions());
    // we cannot merge cells included in an array formula
    sheet.setArrayFormula("A1:A4*B1:B4", CellRangeAddress.valueOf("C2:F5"));
    for (String ref : Arrays.asList(// identity
    "C2:F5", // contains
    "D3:E4", // contains
    "B1:G6", // 1x1 corner intersection
    "B1:C2", // 1x1 corner intersection
    "F1:G2", // 1x1 corner intersection
    "F5:G6", // 1x1 corner intersection
    "B5:C6", // 1-row/1-column intersection
    "B1:C6", // 1-row/1-column intersection
    "B1:G2", // 1-row/1-column intersection
    "F1:G6", // 1-row/1-column intersection
    "B5:G6", // 2x2 corner intersection
    "B1:D3", // 2x2 corner intersection
    "E1:G3", // 2x2 corner intersection
    "E4:G6", // 2x2 corner intersection
    "B4:D6", // 2-row/2-column intersection
    "B1:D6", // 2-row/2-column intersection
    "B1:G3", // 2-row/2-column intersection
    "E1:G6", // 2-row/2-column intersection
    "B4:G6")) {
        CellRangeAddress cra = CellRangeAddress.valueOf(ref);
        try {
            sheet.addMergedRegion(cra);
            fail("expected exception with ref " + ref);
        } catch (IllegalStateException e) {
            String msg = "The range " + cra.formatAsString() + " intersects with a multi-cell array formula. You cannot merge cells of an array.";
            assertEquals(msg, e.getMessage());
        }
    }
    //the number of merged regions remains the same
    assertEquals(expectedNumMergedRegions, sheet.getNumMergedRegions());
    // we can merge non-intersecting cells
    for (String ref : Arrays.asList(//above
    "C1:F1", //right
    "G2:G5", //bottom
    "C6:F6", "B2:B5", "H7:J9")) {
        CellRangeAddress cra = CellRangeAddress.valueOf(ref);
        try {
            sheet.addMergedRegion(cra);
            expectedNumMergedRegions++;
            assertEquals(expectedNumMergedRegions, sheet.getNumMergedRegions());
        } catch (IllegalStateException e) {
            fail("did not expect exception with ref: " + ref + "\n" + e.getMessage());
        }
    }
    workbook.close();
}

