    String[] formats = { "##.##", "[WHITE]##.##", "[BLACK]##.##;[RED]-##.##", "[COLOR11]##.##;[COLOR 43]-##.00" };
    for (String format : formats) {
        assertEquals("Wrong format for: " + format, "12.34", dfUS.formatRawCellContents(12.343, -1, format));
