            if (truths.length <= j) {
                continue;
            }
            String truth = clean(truths[j]);
            String testKey = truths[0] + ":" + truths[1] + ":" + headers[j];
            assertEquals(testKey, truth, formatted);
        }
        truthLine = reader.readLine();
    }
    wb.close();
    reader.close();
}

