@Test
public void drawBorders() throws IOException {
    CellRangeAddress a1c3 = new CellRangeAddress(0, 2, 0, 2);
    PropertyTemplate pt = new PropertyTemplate();
    pt.drawBorders(a1c3, BorderStyle.THIN, BorderExtent.ALL);
    for (int i = 0; i <= 2; i++) {
        for (int j = 0; j <= 2; j++) {
            assertEquals(4, pt.getNumBorders(i, j));
            assertEquals(BorderStyle.THIN, pt.getBorderStyle(i, j, CellUtil.BORDER_TOP));
            assertEquals(BorderStyle.THIN, pt.getBorderStyle(i, j, CellUtil.BORDER_BOTTOM));
            assertEquals(BorderStyle.THIN, pt.getBorderStyle(i, j, CellUtil.BORDER_LEFT));
            assertEquals(BorderStyle.THIN, pt.getBorderStyle(i, j, CellUtil.BORDER_RIGHT));
        }
    }
    pt.drawBorders(a1c3, BorderStyle.MEDIUM, BorderExtent.OUTSIDE);
    for (int i = 0; i <= 2; i++) {
        for (int j = 0; j <= 2; j++) {
            assertEquals(4, pt.getNumBorders(i, j));
            if (i == 0) {
