@Test
public void testPutCompressedUnicode() {
    byte[] output = new byte[100];
    byte[] expected_output = { (byte) 'H', (byte) 'e', (byte) 'l', (byte) 'l', (byte) 'o', (byte) ' ', (byte) 'W', (byte) 'o', (byte) 'r', (byte) 'l', (byte) 'd', (byte) 0xAE };
    String input = new String(expected_output, Charset.forName(StringUtil.getPreferredEncoding()));
    StringUtil.putCompressedUnicode(input, output, 0);
    for (int j = 0; j < expected_output.length; j++) {
        assertEquals("testing offset " + j, expected_output[j], output[j]);
    }
    StringUtil.putCompressedUnicode(input, output, 100 - expected_output.length);
    for (int j = 0; j < expected_output.length; j++) {
        assertEquals("testing offset " + j, expected_output[j], output[100 + j - expected_output.length]);
    }
    try {
        StringUtil.putCompressedUnicode(input, output, 101 - expected_output.length);
        fail("Should have caught ArrayIndexOutOfBoundsException");
    } catch (ArrayIndexOutOfBoundsException ignored) {
        // as expected
    }
}

